package com.isoform

import com.facebook.react.bridge.ReadableArray
import com.facebook.react.module.annotations.ReactModule
import com.facebook.react.uimanager.SimpleViewManager
import com.facebook.react.uimanager.ThemedReactContext
import com.facebook.react.uimanager.ViewManagerDelegate
import com.facebook.react.viewmanagers.IsoCameraViewManagerDelegate
import com.facebook.react.viewmanagers.IsoCameraViewManagerInterface

/**
 * Bridge between Fabric and `IsoCameraView`: props, commands and events.
 * `IsoCameraViewManagerInterface`/`Delegate` are generated by Codegen from
 * `src/adapters/react-native/camera/native/IsoCameraViewNativeComponent.ts`.
 */
@ReactModule(name = IsoCameraViewManager.NAME)
class IsoCameraViewManager :
  SimpleViewManager<IsoCameraView>(),
  IsoCameraViewManagerInterface<IsoCameraView> {

  private val delegate = IsoCameraViewManagerDelegate(this)

  override fun getDelegate(): ViewManagerDelegate<IsoCameraView> = delegate

  override fun getName(): String = NAME

  override fun createViewInstance(context: ThemedReactContext): IsoCameraView = IsoCameraView(context)

  override fun onDropViewInstance(view: IsoCameraView) {
    view.release()
    super.onDropViewInstance(view)
  }

  // ── props ──

  override fun setFacing(view: IsoCameraView, value: String?) = view.setFacing(value)

  override fun setActive(view: IsoCameraView, value: Boolean) = view.setActive(value)

  override fun setFlash(view: IsoCameraView, value: String?) = view.setFlash(value)

  override fun setTorch(view: IsoCameraView, value: Boolean) = view.setTorch(value)

  override fun setZoom(view: IsoCameraView, value: Float) = view.setZoom(value)

  override fun setZoomGesture(view: IsoCameraView, value: Boolean) = view.setZoomGesture(value)

  override fun setFocusGesture(view: IsoCameraView, value: Boolean) = view.setFocusGesture(value)

  override fun setVideo(view: IsoCameraView, value: Boolean) = view.setVideo(value)

  override fun setAudio(view: IsoCameraView, value: Boolean) = view.setAudio(value)

  override fun setCodeScanner(view: IsoCameraView, value: Boolean) = view.setCodeScanner(value)

  override fun setCodeTypes(view: IsoCameraView, value: ReadableArray?) = view.setCodeTypes(value)

  // ── commands ──

  override fun takePhoto(view: IsoCameraView, requestId: Int, flash: String) = view.takePhoto(requestId, flash)

  override fun startRecording(view: IsoCameraView, requestId: Int) = view.startRecording(requestId)

  override fun stopRecording(view: IsoCameraView, requestId: Int) = view.stopRecording(requestId)

  override fun requestPermission(view: IsoCameraView) = view.requestPermission()

  // ── events (native name → JS prop) ──

  override fun getExportedCustomDirectEventTypeConstants(): Map<String, Any> =
    IsoCameraView.EVENTS.associateWith { mapOf("registrationName" to "on" + it.removePrefix("top")) }

  companion object {
    const val NAME = "IsoCameraView"
  }
}
